import {defaults} from './engine.mjs';
const $=id=>document.getElementById(id),nf=new Intl.NumberFormat('ko-KR',{maximumFractionDigits:0}),money=v=>nf.format(v)+'원',pct=v=>(v>0?'+':'')+v.toFixed(2)+'%',esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={'005930':'삼성전자','000660':'SK하이닉스','035420':'NAVER'},reasons={stop:'손절',gap_stop:'갭 손절',day_exit:'당일 청산',daily_loss_exit:'일 손실 제한'};
let result=null,demo=null,busy=false,worker=null,position=0,timer=null,deferredPrompt=null;
function tab(name){if(!['test','watch','paper','rules'].includes(name))throw Error('화면 이름 오류');for(const v of document.querySelectorAll('.view'))v.hidden=v.id!==name;for(const b of document.querySelectorAll('[data-tab]')){b.classList.toggle('active',b.dataset.tab===name);if(b.dataset.tab===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}if(name!=='paper')pause();}
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>tab(b.dataset.tab);
function message(s,error=false){$('status').textContent=s;$('status').classList.toggle('error',error);}
function sourceChanged(){const own=$('source').value==='csv';$('uploads').hidden=!own;$('source-help').textContent=own?'실제 데이터를 선택하세요. 데이터 정확성은 별도로 확인해야 합니다.':'상승 편향을 넣은 가상 데이터입니다. 실제 성과가 아닙니다.';if(own){$('from').value='';$('to').value='';}else if(demo)setDates(demo.bars);message('설정을 바꾼 뒤 다시 실행하세요. 표시된 결과는 마지막 실행 기준입니다.');}
$('source').onchange=sourceChanged;
function setDates(text){const dates=text.trim().split(/\r?\n/).slice(1).map(l=>l.slice(0,10)).sort();$('from').value=dates[0];$('to').value=dates.at(-1);}
async function readFiles(){let texts={},total=0;for(const k of ['bars','index','daily']){const file=$(k+'-file').files[0];if(!file)throw Error('종목 분봉·시장지표·일봉 파일 3개를 모두 선택하세요.');if(file.size>15*1024*1024)throw Error('파일당 15MB 이하로 나눠 주세요.');total+=file.size;if(total>30*1024*1024)throw Error('파일 3개의 총 크기는 30MB 이하여야 합니다.');texts[k]=await file.text();}return texts;}
function config(){const fields=['capital','risk','weight','fee','tax','slip'];for(const k of fields)if(!$(k).reportValidity())throw Error('설정값 범위를 확인하세요.');return {...defaults,capital:Number($('capital').value),risk:Number($('risk').value)/100,neutral_risk:Number($('risk').value)/200,max_weight:Number($('weight').value)/100,fee:Number($('fee').value)/100,sell_tax:Number($('tax').value)/100,slip:Number($('slip').value)/100};}
async function run(){if(busy)throw Error('현재 계산 중입니다.');let data,cfg;try{cfg=config();if($('from').value&&$('to').value&&$('from').value>$('to').value)throw Error('시작일은 종료일보다 빨라야 합니다.');data=$('source').value==='demo'?demo:await readFiles();if(!data)throw Error('예제를 불러오지 못했습니다. CSV를 선택하거나 새로고침하세요.');}catch(e){message(e.message,true);throw e;}
 pause();busy=true;$('run').disabled=true;message('계산 중…');try{const output=await new Promise((resolve,reject)=>{worker=new Worker('./worker.mjs',{type:'module'});const timeout=setTimeout(()=>{worker?.terminate();reject(Error('계산 시간이 길어졌습니다. 기간이나 종목 수를 줄여 주세요.'));},120000);worker.onmessage=({data})=>{clearTimeout(timeout);worker.terminate();worker=null;data.error?reject(Error(data.error)):resolve(data.result);};worker.onerror=()=>{clearTimeout(timeout);worker.terminate();worker=null;reject(Error('계산을 시작하지 못했습니다. 새로고침한 뒤 다시 시도하세요.'));};worker.postMessage({...data,config:cfg,adaptive:$('adaptive').checked,from:$('from').value,to:$('to').value,kind:$('source').value==='demo'?'SYNTHETIC_SOFTWARE_TEST':'USER_SUPPLIED_NOT_VERIFIED'});});result=output;render();message('완료 · '+result.summary.trades+'건. '+(result.summary.data_kind==='SYNTHETIC_SOFTWARE_TEST'?'합성 예제 결과이며 실제 성과가 아닙니다.':'직접 입력한 데이터 기준 결과입니다.'));try{localStorage.setItem('tm-preferences-v1',JSON.stringify({capital:cfg.capital,risk:cfg.risk*100,weight:cfg.max_weight*100,fee:cfg.fee*100,tax:cfg.sell_tax*100,slip:cfg.slip*100}));}catch{}return result.summary;}catch(e){message(e.message,true);throw e;}finally{busy=false;$('run').disabled=false;}}
$('run').onclick=()=>run().catch(()=>{});
function chart(){let c=result.curve,all=[{equity:result.summary.initial},...c],lo=all.reduce((v,x)=>Math.min(v,x.equity),Infinity),hi=all.reduce((v,x)=>Math.max(v,x.equity),-Infinity),pad=Math.max((hi-lo)*.12,result.summary.initial*.0005);lo-=pad;hi+=pad;const w=800,h=250,x=i=>70+i/(all.length-1)*720,y=v=>225-(v-lo)/(hi-lo)*205;const step=Math.max(1,Math.floor(all.length/600));let points=all.filter((_,i)=>i%step===0||i===all.length-1).map((r,j)=>{const i=j*step>=all.length?all.length-1:Math.min(j*step,all.length-1);return x(i)+','+y(r.equity);});const finalPoint=x(all.length-1)+','+y(all.at(-1).equity);if(points.at(-1)!==finalPoint)points.push(finalPoint);let lines='';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;lines+=`<line x1="70" x2="790" y1="${y(v)}" y2="${y(v)}" stroke="#28394f"/><text x="60" y="${y(v)+4}" text-anchor="end" fill="#a3b2c9" font-size="12">${(v/10000).toFixed(1)}만</text>`;}
$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="평가자산 곡선, 시작 ${money(result.summary.initial)}, 종료 ${money(result.summary.final)}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3ee7b6" stop-opacity=".22"/><stop offset="1" stop-color="#3ee7b6" stop-opacity="0"/></linearGradient></defs>${lines}<line x1="70" x2="790" y1="${y(result.summary.initial)}" y2="${y(result.summary.initial)}" stroke="#66837c" stroke-dasharray="5 5"/><polygon points="70,225 ${points.join(' ')} 790,225" fill="url(#fill)"/><polyline points="${points.join(' ')}" stroke="#3ee7b6" stroke-width="2.5" fill="none"/></svg>`;}
function render(){const s=result.summary;$('kind').textContent=s.data_kind==='SYNTHETIC_SOFTWARE_TEST'?'합성 예제 · 실제 성과 아님':'입력 CSV · 정확성 미검증';$('final').textContent=money(s.final);$('gain').textContent='손익 '+money(s.final-s.initial);$('ret').textContent=pct(s.return_pct);$('ret').className=s.return_pct>=0?'up':'down';$('mdd').textContent=pct(s.MDD_pct);$('mdd').className='down';$('count').textContent=s.trades+'건';$('wins').textContent='승률 '+(s.win_rate_pct===null?'—':s.win_rate_pct.toFixed(1)+'%');$('pf').textContent='PF '+(s.profit_factor===null?'—':s.profit_factor.toFixed(2))+' · 평균 R '+(s.mean_R===null?'—':s.mean_R.toFixed(2));$('period').textContent=result.curve[0].timestamp.slice(0,10)+' ~ '+result.curve.at(-1).timestamp.slice(0,10);$('trades').innerHTML=result.trades.length?result.trades.slice(-30).reverse().map(t=>`<tr><td>${esc(names[t.symbol]||t.symbol)}<span class="code">${esc(t.symbol)}</span></td><td>${esc(t.entry_time.slice(5,16))}<br><span class="muted">${esc(t.exit_time.slice(5,16))}</span></td><td>${t.qty}주</td><td class="${t.pnl>=0?'up':'down'}">${money(t.pnl)}<span class="code">${t.R.toFixed(2)}R</span></td><td>${reasons[t.reason]||esc(t.reason)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">조건에 맞는 거래가 없습니다. 데이터·준비기간과 시장 조건을 확인하세요.</td></tr>';$('export').disabled=false;chart();position=0;$('scrub').max=result.curve.length-1;$('scrub').value=0;$('scrub').disabled=false;$('play').disabled=false;$('reset').disabled=false;replay();}
function download(name,text,mime){const u=URL.createObjectURL(new Blob([mime==='text/csv'?'\uFEFF'+text:text],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('export').onclick=()=>{if(!result)return;download('TREND_MASTER_result.json',JSON.stringify(result,null,2),'application/json');};
$('template').onclick=()=>download('TREND_MASTER_csv_template.csv','timestamp,symbol,open,high,low,close,volume\n2026-10-07 09:00:00,005930,60000,60100,59900,60050,120000\n','text/csv');
function pause(){if(timer)clearInterval(timer);timer=null;$('play').textContent='재생';}
function replay(){if(!result)return;const r=result.curve[position];$('scrub').value=position;$('replay-time').textContent=r.timestamp.slice(0,16)+' KST';$('replay-equity').textContent=money(r.equity);const closed=result.trades.filter(t=>t.exit_time<=r.timestamp);$('replay-count').textContent=closed.length+'건';let events=[];for(const t of result.trades){if(t.entry_time<=r.timestamp)events.push({time:t.entry_time,label:'진입',t});if(t.exit_time<=r.timestamp)events.push({time:t.exit_time,label:'청산',t});}events.sort((a,b)=>b.time.localeCompare(a.time));$('events').innerHTML=events.slice(0,8).map(({time,label,t})=>`<div class="event"><div><b>${label} · ${esc(names[t.symbol]||t.symbol)}</b><small>${time.slice(5,16)} · ${t.qty}주 · ${money(label==='진입'?t.entry:t.exit)}</small></div><span class="${label==='청산'?(t.pnl>=0?'up':'down'):'muted'}">${label==='청산'?money(t.pnl):'신호 진입'}</span></div>`).join('')||'<p class="empty">이 시점까지 발생한 거래가 없습니다.</p>';}
$('play').onclick=()=>{if(!result)return;if(timer){pause();return;}if(position>=result.curve.length-1)position=0;$('play').textContent='일시정지';timer=setInterval(()=>{position=Math.min(result.curve.length-1,position+Number($('speed').value));replay();if(position===result.curve.length-1)pause();},150);};$('scrub').oninput=()=>{pause();position=Number($('scrub').value);replay();};$('reset').onclick=()=>{pause();position=0;replay();};document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;});$('install').onclick=async()=>{if(deferredPrompt){await deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;}else $('install-help').showModal();};$('close-help').onclick=()=>$('install-help').close();
async function init(){try{const p=JSON.parse(localStorage.getItem('tm-preferences-v1')||'null');if(p)for(const k of ['capital','risk','weight','fee','tax','slip'])if(Number.isFinite(p[k]))$(k).value=p[k];}catch{}try{const data=await Promise.all(['bars','index','daily'].map(async k=>{const r=await fetch('./data/synthetic_'+k+'.csv');if(!r.ok)throw Error('예제 다운로드 실패');return [k,await r.text()];}));demo=Object.fromEntries(data);setDates(demo.bars);await run();}catch(e){message(e.message,true);}if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController;for(const t of [{name:'read_backtest_result',title:'백테스트 결과 조회',description:'마지막 실행 결과를 조회합니다. 합성/입력 데이터 구분을 포함합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('빈 객체만 허용합니다.');return result?{summary:result.summary,tradeCount:result.trades.length}: {status:'no_result'};}},{name:'run_selected_backtest',title:'선택한 데이터 백테스트 실행',description:'화면에서 선택한 데이터와 설정으로 계산하고 결과 화면을 갱신합니다. 증권사 주문을 보내지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||Object.keys(input).length)throw Error('빈 객체만 허용합니다.');return await run();}}])try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
init();
let scanResult=null;
function parseUniverse(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/),heads=lines.shift().split(',').map(x=>x.trim());for(const k of ['symbol','name','market','eligible','as_of'])if(!heads.includes(k))throw Error('종목 마스터 필수 열: '+k);return lines.filter(x=>x.trim()).map(line=>{const a=line.split(',');let r=Object.fromEntries(heads.map((k,i)=>[k,a[i]?.trim()]));if(!['true','false'].includes(r.eligible))throw Error('eligible은 true 또는 false로 명시하세요.');return {...r,eligible:r.eligible==='true'};});}
async function scan(){if(busy)throw Error('계산 중입니다.');try{const cfg=config(),isDemo=$('source').value==='demo',data=isDemo?demo:await readFiles();if(!data)throw Error('데이터 없음');let universe;if(isDemo){const day=data.bars.trim().split(/\r?\n/).slice(1).map(l=>l.slice(0,10)).sort().at(-1);universe=Object.entries(names).map(([symbol,name])=>({symbol,name,market:'KOSPI',eligible:true,as_of:day}));}else{const file=$('universe-file').files[0];if(!file)throw Error('실제 데이터에는 코스피 종목 마스터가 필요합니다.');if(file.size>2000000)throw Error('종목 마스터는 2MB 이하를 사용하세요.');universe=parseUniverse(await file.text());}busy=true;$('scan').disabled=true;$('scan-status').textContent='검토 중…';scanResult=await new Promise((resolve,reject)=>{const w=new Worker('./worker.mjs',{type:'module'}),limit=setTimeout(()=>{w.terminate();reject(Error('데이터를 줄여 다시 실행하세요.'));},120000);w.onmessage=({data})=>{clearTimeout(limit);w.terminate();data.error?reject(Error(data.error)):resolve(data.result);};w.onerror=()=>{clearTimeout(limit);w.terminate();reject(Error('계산 오류'));};w.postMessage({...data,mode:'scan',config:cfg,universe,kind:isDemo?'SYNTHETIC_SOFTWARE_TEST':'USER_SUPPLIED_NOT_VERIFIED',completeConfirmed:isDemo||$('complete-bars').checked});});$('universe-total').textContent=scanResult.universe_count+'개';$('universe-covered').textContent=scanResult.bar_covered+'개';$('universe-pass').textContent=scanResult.eligible_count+'개';$('universe-signals').textContent=scanResult.signals+'개';$('scan-time').textContent=scanResult.timestamp.slice(0,16)+' · '+scanResult.regime;$('scan-status').textContent=(isDemo?'합성 3종목 예제 · 실제 코스피 감시 아님':'입력 마스터 기준 · 실시간 시세 미연결')+' · 일봉 '+scanResult.daily_covered+'/'+scanResult.universe_count+'종목';$('watch-detail').hidden=true;renderWatch();return {timestamp:scanResult.timestamp,coverage:scanResult.bar_covered,signals:scanResult.signals};}catch(e){$('scan-status').textContent=e.message;throw e;}finally{busy=false;$('scan').disabled=false;}}
$('scan').onclick=()=>scan().catch(()=>{});
function renderWatch(){if(!scanResult)return;const query=$('watch-search').value.trim().toLowerCase(),filter=$('watch-filter').value,rows=scanResult.rows.filter(r=>(filter==='all'||r.state===filter)&&(!query||(r.name+r.symbol).toLowerCase().includes(query)));$('watch-rows').innerHTML=rows.slice(0,100).map(r=>`<tr><td>${esc(r.name)}<span class="code">${esc(r.symbol)}</span></td><td><span class="${r.state==='진입 조건 충족'?'up':'muted'}">${r.state}</span><span class="watch-reason">${esc(r.reasons.join(' · ')||'다음 봉 체결가·현금 확인 필요')}</span></td><td>${r.plan?money(r.plan.pivot):'—'}</td><td>${r.plan?money(r.plan.stop):'—'}</td><td>${r.plan?r.plan.qty+'주':'—'}</td><td><button class="quiet" data-symbol="${esc(r.symbol)}">검토</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">해당하는 종목 없음</td></tr>';for(const b of $('watch-rows').querySelectorAll('button'))b.onclick=()=>detailWatch(b.dataset.symbol);}
$('watch-search').oninput=renderWatch;$('watch-filter').onchange=renderWatch;
function detailWatch(symbol){const r=scanResult.rows.find(r=>r.symbol===symbol),p=r.plan;$('watch-detail').hidden=false;$('watch-detail').innerHTML=`<h2>${esc(r.name)} · 매수·매도 검토</h2><p>${esc(scanResult.timestamp)} 기준 ${r.state}. ${esc(r.reasons.join(' · '))}</p>${p?`<div class="watch-plan"><div><span>돌파 기준</span><strong>${money(p.pivot)}</strong></div><div><span>체결 추정가</span><strong>${money(p.entry_estimate)}</strong></div><div><span>추격 제한</span><strong>${money(p.entry_ceiling)}</strong></div><div><span>초기 손절 기준</span><strong>${money(p.stop)}</strong></div><div><span>단일 포지션 수량</span><strong>${p.qty}주</strong></div><div><span>비용 포함 계획 위험</span><strong>${money(p.planned_risk)}</strong></div></div><h3>매수 검토</h3><p>모든 조건이 충족된 완성봉 다음 봉에서만 진입을 검토합니다. 실제 체결가가 추격 제한을 넘거나 손절 아래이면 건너뜁니다. 현재 상태가 ‘진입 조건 충족’이 아니라면 위 숫자는 관찰용입니다.</p><h3>매도 검토</h3><p>초기 손절 ${money(p.stop)}. 보유 중에는 진입 이후 고가 − 2.5ATR로 손절을 올리되 기존 손절 아래로 내리지 않습니다. 현재 ATR 기준 추적 거리는 ${money(p.trailing_gap)}이며 이후 ATR 변화로 달라집니다. 손절 아래 시가로 갭 하락하면 손절가 체결을 보장하지 못합니다. 15:15 당일 청산, 계좌 일 손실 1.5% 도달 시 다음 이용 가능한 봉에서 청산합니다.</p>`:'<p>데이터·적격성·전일 선별 조건을 먼저 확인해야 하므로 매수가·손절가·수량을 제시하지 않습니다.</p>'}<p class="help">현재 보유·계좌 상태는 연결되지 않았습니다. 매수·매도 주문을 전송하지 않습니다.</p>`;$('watch-detail').scrollIntoView({behavior:'smooth',block:'start'});}
$('universe-template').onclick=()=>download('kospi_universe_template.csv','symbol,name,market,eligible,as_of\n005930,삼성전자,KOSPI,false,2026-10-07\n','text/csv');
